package itda.medicalsupport.controller;
import itda.common.dto.ApiResponse; import itda.common.security.CurrentUser; import itda.medicalsupport.dto.MedicalSupportProgramResponse; import itda.medicalsupport.service.MedicalSupportQueryService; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/medical-support/programs") @RequiredArgsConstructor public class MedicalSupportController {private final MedicalSupportQueryService service; @GetMapping public ResponseEntity<ApiResponse<List<MedicalSupportProgramResponse>>> list(@AuthenticationPrincipal CurrentUser user){return ResponseEntity.ok(ApiResponse.ok(service.listForUser(user.id()),"거주 지역의 반려동물 의료비 지원사업을 조회했습니다."));} @GetMapping("/{programId}") public ResponseEntity<ApiResponse<MedicalSupportProgramResponse>> detail(@AuthenticationPrincipal CurrentUser user,@PathVariable long programId){return ResponseEntity.ok(ApiResponse.ok(service.detail(user.id(),programId),"반려동물 의료비 지원사업을 조회했습니다."));}}
